// Admin-settings data: readable by admins only. AuthorizedEmail is
// staff-readable because dozens of staff views resolve user identities from
// it; its secret fields are stripped by FIELD_DENYLIST below before any row
// leaves the backend.
const ADMIN_READABLE = new Set<string>([
  'AccountDeletionRequest',
  'AdminAuditLog',
  'AutomationRule',
  'CorebridgeLog',
  'EmailGroup',
  'EmailNotificationSettings',
  'FailedAdminAttempt',
  'FeatureReport',
  'SyncConflict',
  'TimeClockPunchException',
  'UserSession',

  // GL/accounting configuration (masterplan A-29) — admin tier only.
  'COGSAccount',
  'IncomeAccount',
  'TaxAgency',
]);

// Fields that must never leave the backend regardless of role. These hold
// credentials, bearer ******, biometric descriptors, and session-revocation
// state; no staff-facing page has a legitimate read for them.
const FIELD_DENYLIST: Record<string, string[]> = {
  AuthorizedEmail: [
    'password_hash',
    'password_reset_token',
    'password_reset_token_hash',
    'password_reset_expires',
    'onboarding_token',
    'onboarding_token_hash',
    'onboarding_expires',
    'session_not_before',
    'failed_login_count',
    'login_locked_until',
    'face_descriptors',
  ],
};

const MAX_LIMIT = 5000;
const MAX_SKIP = 100000;
const MAX_QUERY_BYTES = 4000;

// Payroll/HR rows are visible to their owner or an admin — not to every
// coworker. Entities listed here are filtered to user_email = caller
// whenever the caller is not an admin.
const OWNER_SCOPED = new Set([
  'TimeEntry',
  'TimeClockAudit',
  'TimeClockBreak',
  'TimeClockCorrectionRequest',
  'TimeClockLaborSegment',
  'TimeClockPayPeriod',
  'TimeClockWorkPause',
  'TimeOffRequest',
  'UserPTOBalance',
]);
const SORT_PATTERN = /^(-?[A-Za-z_][\w.]*)(\s*,\s*-?[A-Za-z_][\w.]*){0,3}$/;

function projectItem(entityName: string, item: any, user?: any) {
  const denied = [...(FIELD_DENYLIST[entityName] || []),
    ...((user?.admin_permissions?.denied_fields?.[entityName]) || [])];
  if (!denied || !item || typeof item !== 'object') return item;
  const clean = { ...item };
  for (const field of denied) delete clean[field];
  return clean;
}

function cleanSort(value: unknown, entityName: string) {
  const sort = String(value || '').trim();
  if (!sort) return '';
  if (sort.length > 200 || !SORT_PATTERN.test(sort)) {
    throw Object.assign(new Error('Staff read sort is invalid.'), { status: 400 });
  }
  // Denylisted fields must not be usable as a sort oracle either.
  const denied = new Set(FIELD_DENYLIST[entityName] || []);
  for (const part of sort.split(',')) {
    const field = part.trim().replace(/^-/, '');
    if (denied.has(field)) {
      throw Object.assign(new Error('Staff read sort field is not permitted.'), { status: 400 });
    }
  }
  return sort;
}

// The only filter operators a staff read may use. Comparison/set operators are
// safe on ordinary fields; logical operators ($or/$and/$nor) stay refused so a
// filter can never assemble a query the gateway did not scope itself.
const ALLOWED_OPERATORS = new Set([
  '$eq', '$ne', '$in', '$nin', '$gt', '$gte', '$lt', '$lte', '$exists', '$regex', '$options',
]);
const MAX_IN_VALUES = 200;
const MAX_REGEX_LENGTH = 200;

function checkOperatorValue(operator: string, value: unknown) {
  if (operator === '$in' || operator === '$nin') {
    if (!Array.isArray(value) || value.length === 0 || value.length > MAX_IN_VALUES) {
      throw Object.assign(new Error(`Staff read ${operator} needs 1 to ${MAX_IN_VALUES} values.`), { status: 400 });
    }
    for (const entry of value) {
      if (entry && typeof entry === 'object') {
        throw Object.assign(new Error('Staff read filter operators are not allowed.'), { status: 400 });
      }
    }
    return;
  }
  if (operator === '$exists') {
    if (typeof value !== 'boolean') {
      throw Object.assign(new Error('Staff read $exists needs true or false.'), { status: 400 });
    }
    return;
  }
  if (operator === '$regex' || operator === '$options') {
    if (typeof value !== 'string' || value.length > MAX_REGEX_LENGTH) {
      throw Object.assign(new Error('Staff read search pattern is not allowed.'), { status: 400 });
    }
    return;
  }
  if (value !== null && typeof value === 'object') {
    throw Object.assign(new Error('Staff read filter operators are not allowed.'), { status: 400 });
  }
}

function cleanQuery(value: unknown, entityName: string) {
  if (value == null) return null;
  if (typeof value !== 'object' || Array.isArray(value)) {
    throw Object.assign(new Error('Staff read filter must be an object.'), { status: 400 });
  }
  // Operators are allowed only directly on a top-level field, never on a
  // denylisted field (that would turn output-denied data into a boolean
  // oracle) and never nested deeper than one level.
  const deniedFields = new Set(FIELD_DENYLIST[entityName] || []);
  const stack: any[] = [{ node: value, field: '', depth: 0 }];
  while (stack.length) {
    const { node, field, depth } = stack.pop();
    if (!node || typeof node !== 'object' || Array.isArray(node)) continue;
    for (const [key, val] of Object.entries(node)) {
      if (key.startsWith('$')) {
        if (depth !== 1 || !field) {
          throw Object.assign(new Error('Staff read filter operators are not allowed.'), { status: 400 });
        }
        if (!ALLOWED_OPERATORS.has(key)) {
          throw Object.assign(new Error('Staff read filter operators are not allowed.'), { status: 400 });
        }
        if (deniedFields.has(field)) {
          throw Object.assign(new Error('Staff read filter operators are not allowed.'), { status: 400 });
        }
        checkOperatorValue(key, val);
        continue;
      }
      if (val && typeof val === 'object') {
        // Exactly one level below a top-level field may hold operators.
        stack.push({ node: val, field: key, depth: depth + 1 });
      }
    }
  }
  let serialized;
  try {
    serialized = JSON.stringify(value);
  } catch {
    throw Object.assign(new Error('Staff read filter must be JSON-serializable.'), { status: 400 });
  }
  if (serialized.length > MAX_QUERY_BYTES) {
    throw Object.assign(new Error('Staff read filter is too large.'), { status: 400 });
  }
  return value;
}

function cleanLimit(value: unknown, fallback: number) {
  if (value == null || value === '') return fallback;
  const parsed = Math.floor(Number(value));
  if (!Number.isFinite(parsed) || parsed < 1) {
    throw Object.assign(new Error(`Staff read limit must be between 1 and ${MAX_LIMIT}.`), { status: 400 });
  }
  // A caller asking for more than one page gets the page maximum rather than a
  // failed read; callers that need every row page with skip.
  return Math.min(parsed, MAX_LIMIT);
}

function cleanSkip(value: unknown) {
  if (value == null || value === '') return 0;
  const parsed = Math.floor(Number(value));
  if (!Number.isFinite(parsed) || parsed < 0 || parsed > MAX_SKIP) {
    throw Object.assign(new Error(`Staff read offset must be between 0 and ${MAX_SKIP}.`), { status: 400 });
  }
  return parsed;
}

const MAX_CURSOR_BYTES = 4000;
const MAX_FIELD_LIST = 200;
const FIELD_NAME_PATTERN = /^[A-Za-z_][\w.]*$/;
const COUNT_PAGE = 500;
const COUNT_MAX_ROWS = 100000;

// Continuation cursor for options-object reads — opaque to the gateway, only
// size-checked so a request can't smuggle an oversized token.
function cleanCursor(value: unknown) {
  const cursor = String(value || '').trim();
  if (!cursor) return '';
  if (cursor.length > MAX_CURSOR_BYTES) {
    throw Object.assign(new Error('Staff read cursor is invalid.'), { status: 400 });
  }
  return cursor;
}

// Optional field projection — dotted paths allowed so callers pull only the
// fields a view needs. Denylisted fields still get stripped by projectItem on
// the way out, so requesting one can never leak it.
function cleanFields(value: unknown) {
  if (value == null || value === '') return null;
  if (!Array.isArray(value) || value.length > MAX_FIELD_LIST) {
    throw Object.assign(new Error('Staff read fields list is invalid.'), { status: 400 });
  }
  const out = [...new Set(value.map((f) => String(f || '').trim()).filter((f) => FIELD_NAME_PATTERN.test(f)))];
  return out.length ? out : null;
}

// Count the full matching set, not one bounded page — the old path counted
// only the limit/skip window and under-reported anything larger. Prefers the
// entity count() API; falls back to a paged tally (capped + honestly flagged)
// when a backend does not expose it.
async function countRows(entity: any, query: any) {
  const countQuery = query && typeof query === 'object' ? query : {};
  if (typeof entity?.count === 'function') {
    try {
      const total = Number(await entity.count(countQuery));
      if (Number.isFinite(total) && total >= 0) return { count: total, truncated: false };
    } catch { /* fall back to the paged tally below */ }
  }
  let scanned = 0;
  while (scanned < COUNT_MAX_ROWS) {
    const page = await entity.filter(countQuery, null, COUNT_PAGE, scanned);
    if (!Array.isArray(page)) break;
    scanned += page.length;
    if (page.length < COUNT_PAGE) return { count: scanned, truncated: false };
  }
  return { count: scanned, truncated: true };
}

// Module-scope per-entry cache — identical reads within the TTL (mount storms:
// parallel component reads and subscribe checks) collapse to a single upstream
// entity read while an isolate stays warm. Writes go through staffEntityWrite,
// so a stale read for up to 45s is an accepted trade for the shared rate
// budget. Only 200 results are cached: an error must never be served twice.
const staffReadCache = new Map();
const staffReadInFlight = new Map();
const STAFF_READ_CACHE_MS = 45_000;

const isRateLimited = (error: any) => Number(error?.status) === 429
  || /rate limit|too many requests|traffic volume/i.test(String(error?.message || error));

function rateLimitRetryAfterMs(error: any) {
  const match = /retry after (\d+)\s*s/i.exec(String(error?.message || error));
  const ms = match ? Number(match[1]) * 1000 : 3000;
  return Math.min(Math.max(ms, 3000), 60000);
}

const MAX_BATCH = 16;
const BATCH_CONCURRENCY = 4;

// The cache key is the request itself plus the scoping the read actually
// applies: role tier, the caller's email for OWNER_SCOPED entities (rows are
// filtered to the owner), and the per-admin denied_fields projection scope.
// Entries share across users and across different batch combinations.
function staffReadEntryKey(request: any, user: any, deniedFieldScope: string) {
  const entity = String(request?.entity || '').trim();
  const ownerScope = user.role !== 'admin' && OWNER_SCOPED.has(entity)
    ? String(user.email || '').trim().toLowerCase() : '';
  return JSON.stringify({
    entity,
    id: request?.id,
    query: request?.query,
    sort: request?.sort,
    limit: request?.limit,
    skip: request?.skip,
    cursor: request?.cursor,
    fields: request?.fields,
    count: request?.count,
  }) + '|' + (user.role === 'admin' ? 'admin' : 'staff') + '|' + ownerScope + '|' + deniedFieldScope;
}

// Cache + in-flight dedupe around readOne. Concurrent identical reads in the
// isolate share one upstream call; only 200 results are retained.
async function readOneCached(base44: any, user: any, request: any, deniedFieldScope: string) {
  const key = staffReadEntryKey(request, user, deniedFieldScope);
  const hit = staffReadCache.get(key);
  if (hit && hit.expires > Date.now()) return hit.result;
  const pending = staffReadInFlight.get(key);
  if (pending) return pending;
  const promise = readOne(base44, user, request)
    .then((result: any) => {
      if (result.status === 200) {
        if (staffReadCache.size > 300) staffReadCache.clear();
        staffReadCache.set(key, { result, expires: Date.now() + STAFF_READ_CACHE_MS });
      }
      return result;
    })
    .finally(() => { staffReadInFlight.delete(key); });
  staffReadInFlight.set(key, promise);
  return promise;
}

// One read for an already-authenticated staff user. Returns {status, body} so
// a batch can report each read independently; the single-read path wraps it as
// a normal Response. Authorization, owner scoping and field projection are
// identical for both paths.
async function readOne(base44: any, user: any, body: any) {
  try {
    const entityName = String(body?.entity || '').trim();
    if (!STAFF_READABLE.has(entityName) && !ADMIN_READABLE.has(entityName)) {
      return { status: 403, body: { error: 'This record type cannot be read here.' } };
    }
    if (ADMIN_READABLE.has(entityName) && user.role !== 'admin') {
      return { status: 403, body: { error: 'This record type requires a CCS admin.' } };
    }

    const entity = base44.asServiceRole.entities[entityName];
    const ownerEmail = user.role === 'admin' ? '' : String(user.email).trim().toLowerCase();
    const id = String(body?.id || '').trim();
    if (id) {
      const item = await entity.get(id).catch((e: any) => (Number(e?.status) === 404 ? null : Promise.reject(e)));
      if (!item) return { status: 404, body: { error: 'Record not found.' } };
      if (OWNER_SCOPED.has(entityName) && ownerEmail && String(item?.user_email || '').trim().toLowerCase() !== ownerEmail) {
        return { status: 404, body: { error: 'Record not found.' } };
      }
      return { status: 200, body: { success: true, item: projectItem(entityName, item, user) } };
    }

    const query = cleanQuery(body?.query, entityName);
    const sort = cleanSort(body?.sort, entityName);
    const limit = cleanLimit(body?.limit, 100);
    const skip = cleanSkip(body?.skip);
    const cursor = cleanCursor(body?.cursor);
    const fields = cleanFields(body?.fields);
    let effectiveQuery = query;
    if (OWNER_SCOPED.has(entityName) && ownerEmail) {
      effectiveQuery = { ...(effectiveQuery || {}), user_email: ownerEmail };
    }
    if (body?.count === true) {
      const counted = await countRows(entity, effectiveQuery);
      return { status: 200, body: { success: true, count: counted.count, truncated: counted.truncated } };
    }
    let rows: any[] = [];
    let nextCursor: string | null = null;
    let hasMore = false;
    if (cursor || fields) {
      // Options-object read — cursor pagination and/or field projections go
      // through the paged entity API ({sort, limit, skip, cursor, fields}).
      // A cursor continues a previous page, so it replaces skip entirely.
      const options: any = { sort: sort || undefined, limit };
      if (!cursor && skip) options.skip = skip;
      if (cursor) options.cursor = cursor;
      if (fields) options.fields = fields;
      const page = effectiveQuery
        ? await entity.filter(effectiveQuery, options)
        : await entity.list(options);
      const pageRows = Array.isArray(page) ? page : page?.items;
      rows = Array.isArray(pageRows) ? pageRows : [];
      nextCursor = !Array.isArray(page) && typeof page?.next_cursor === 'string' && page.next_cursor
        ? page.next_cursor : null;
      hasMore = !Array.isArray(page) && (page?.has_more === true || Boolean(nextCursor));
    } else {
      const items = effectiveQuery
        ? await entity.filter(effectiveQuery, sort || null, limit, skip)
        : await entity.list(sort || null, limit, skip);
      rows = Array.isArray(items) ? items : [];
    }
    const scopedRows = OWNER_SCOPED.has(entityName) && ownerEmail
      ? rows.filter((row) => String(row?.user_email || '').trim().toLowerCase() === ownerEmail)
      : rows;
    // `truncated` means "there may be more rows past this window" — a full
    // page or a live continuation cursor both raise it so callers can page on
    // instead of mistaking a clamped read for the whole set.
    const payload: any = {
      success: true,
      items: scopedRows.map((row) => projectItem(entityName, row, user)),
      returned: scopedRows.length,
      truncated: hasMore || Boolean(nextCursor) || rows.length >= limit,
    };
    if (nextCursor) payload.next_cursor = nextCursor;
    return { status: 200, body: payload };
  } catch (error: any) {
    // A platform rate limit is transient whatever status it arrives with:
    // hand it back as 429 so the browser backs off and retries instead of
    // surfacing a hard failure.
    if (isRateLimited(error)) {
      return { status: 429, body: { error: 'Data could not be loaded. Try again.', retry_after_ms: rateLimitRetryAfterMs(error) } };
    }
    const status = Number(error?.status || error?.response?.status || 500);
    if ([400, 401, 403, 404, 429].includes(status)) {
      return { status, body: { error: error?.message || 'Staff read failed.' } };
    }
    console.error('staffDataRead error:', error);
    return { status: 500, body: { error: 'Data could not be loaded. Try again.' } };
  }
}

function toResponse(result: { status: number, body: any }) {
  const retryMs = Number(result.body?.retry_after_ms) || 3000;
  const headers: Record<string, string> = result.status === 429
    ? { 'Retry-After': String(Math.max(1, Math.ceil(retryMs / 1000))) } : {};
  return Response.json(result.body, { status: result.status, headers });
}

Deno.serve(async (req) => {
  try {
    // One quick server-side retry at most: longer backoff belongs to the
    // browser, which honors Retry-After and coordinates every open request.
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req), { maxRetries: 1 });
    const entityStatsStart = entityCallIsolateStats();
    const entityCalls = () => entityCallIsolateStats().calls - entityStatsStart.calls;
    const body = await req.json().catch(() => ({}));
    const user = await resolveFleetStaffUser(base44, body?.session_token);
    if (!user?.email) return Response.json({ error: 'Authentication required' }, { status: 401 });
    // Per-admin denied_fields change the field projection, so they scope the
    // per-entry cache alongside the role tier and owner-scoped email.
    const deniedFieldScope = user?.admin_permissions?.denied_fields
      ? JSON.stringify(user.admin_permissions.denied_fields) : '';

    // Batch: many reads behind a single session verification. The "entities"
    // shape returns rows keyed by entity name with per-entity errors beside
    // them — plus a `denied` list of entities this caller may not read, each
    // resolved as an empty read; the "requests" shape returns positional
    // {status, body} results. One failing entry never hides the others — a
    // single bad entity can no longer turn one batch call into a fan-out of
    // individual reads.
    if (Array.isArray(body?.entities) || Array.isArray(body?.requests)) {
      const entityMode = Array.isArray(body.entities);
      const requests = entityMode ? body.entities : body.requests;
      if (requests.length === 0 || requests.length > MAX_BATCH) {
        return Response.json({ error: `Staff read batch needs 1 to ${MAX_BATCH} reads.` }, { status: 400 });
      }
      const entities: Record<string, any> = {};
      const errors: Record<string, any> = {};
      const denied: string[] = [];
      const results: any[] = new Array(requests.length);
      // Once a slice surfaces a rate limit the remaining reads are not issued
      // at all — they resolve as the same 429 so the caller backs off as one.
      let rateLimited = false;
      let rateLimitError = 'Data could not be loaded. Try again.';
      let batchRetryAfterMs = 0;
      for (let start = 0; start < requests.length; start += BATCH_CONCURRENCY) {
        const slice = requests.slice(start, start + BATCH_CONCURRENCY);
        const settled = rateLimited
          ? slice.map(() => ({ status: 429, body: { error: rateLimitError, retry_after_ms: batchRetryAfterMs || 3000 } }))
          : await Promise.all(slice.map((request: any) => readOneCached(base44, user, request, deniedFieldScope)));
        settled.forEach((result, offset) => {
          results[start + offset] = result;
          const name = String(requests[start + offset]?.entity || '').trim();
          if (result.status === 200) {
            entities[name] = result.body?.items ?? result.body?.item ?? result.body?.count;
          } else if (result.status === 403 && name) {
            // A denied entity is an expected authorization outcome, not a batch
            // failure: it resolves as an empty read and is reported in `denied`
            // so the browser stops re-requesting it for this session.
            entities[name] = [];
            if (!denied.includes(name)) denied.push(name);
          } else if (name) {
            errors[name] = {
              status: result.status,
              error: result.body?.error || 'Staff read failed.',
              ...(result.status === 429 ? { retry_after_ms: Number(result.body?.retry_after_ms) || 3000 } : {}),
            };
          }
          if (result.status === 429) {
            batchRetryAfterMs = Math.max(batchRetryAfterMs, Number(result.body?.retry_after_ms) || 3000);
          }
        });
        if (!rateLimited) {
          const limited = settled.find((result) => result.status === 429);
          if (limited) {
            rateLimited = true;
            rateLimitError = limited.body?.error || rateLimitError;
          }
        }
      }
      const batchPayload = entityMode
        ? {
            success: true,
            entity_calls: entityCalls(),
            entities,
            ...(denied.length ? { denied } : {}),
            ...(Object.keys(errors).length ? { errors } : {}),
            ...(batchRetryAfterMs ? { retry_after_ms: batchRetryAfterMs } : {}),
          }
        : { success: true, results, ...(batchRetryAfterMs ? { retry_after_ms: batchRetryAfterMs } : {}) };
      return Response.json(batchPayload);
    }

    const result = await readOneCached(base44, user, body, deniedFieldScope);
    if (result.status === 200 && result.body && typeof result.body === 'object') {
      result.body.entity_calls = entityCalls();
    }
    return toResponse(result);
  } catch (error: any) {
    if (isRateLimited(error)) {
      const retryAfterMs = rateLimitRetryAfterMs(error);
      return Response.json(
        { error: 'Data could not be loaded. Try again.', retry_after_ms: retryAfterMs },
        { status: 429, headers: { 'Retry-After': String(Math.max(1, Math.ceil(retryAfterMs / 1000))) } },
      );
    }
    const status = Number(error?.status || error?.response?.status || 500);
    if ([400, 401, 403, 429].includes(status)) {
      return Response.json({ error: error?.message || 'Staff read failed.' }, { status });
    }
    console.error('staffDataRead error:', error);
    return Response.json({ error: 'Data could not be loaded. Try again.' }, { status: 500 });
  }
});

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function isEntityNotFoundError(error) {
  const status = Number(error?.status || error?.response?.status || error?.response?.statusCode || error?.data?.status || 0);
  if (status === 404) return true;
  const message = String(
    error?.message ||
    error?.response?.data?.message ||
    error?.response?.data?.error ||
    error?.data?.message ||
    error?.data?.error ||
    ""
  ).toLowerCase();
  return message.includes("not found") || message.includes("does not exist");
}

export function expectedBuilderEntityFields(record = {}, nextFields = {}) {
  return Object.fromEntries(
    Object.keys(nextFields || {}).map((field) => [field, record?.[field]])
  );
}

export async function replaceBuilderEntityFieldsIfUnchanged({
  entity,
  id,
  expectedUpdatedAt = "",
  expectedFields,
  nextFields,
  guardFields = {},
  label = "Builder record",
  maxAttempts = 3,
} = {}) {
  const recordId = String(id || "").trim();
  const expectedVersion = String(expectedUpdatedAt || "").trim();
  const expected = expectedFields && typeof expectedFields === "object" && !Array.isArray(expectedFields) ? expectedFields : null;
  const desired = nextFields && typeof nextFields === "object" && !Array.isArray(nextFields) ? nextFields : null;
  const guards = guardFields && typeof guardFields === "object" && !Array.isArray(guardFields) ? guardFields : {};
  const fieldNames = desired ? Object.keys(desired) : [];
  if (!recordId || !expected || !desired || fieldNames.length === 0 || typeof entity?.get !== "function" || typeof entity?.updateMany !== "function") {
    throw new Error(`${label} could not initialize its concurrency-safe update.`);
  }
  for (const fieldName of fieldNames) {
    if (!Object.prototype.hasOwnProperty.call(expected, fieldName)) {
      throw new Error(`${label} is missing the loaded baseline for ${fieldName}.`);
    }
  }

  const attempts = Math.max(1, Math.min(5, Number(maxAttempts) || 3));
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const current = await entity.get(recordId);
    if (!current?.id) throw new Error(`${label} could not be re-read before saving.`);

    for (const [fieldName, value] of Object.entries(guards)) {
      if (!sameValue(current[fieldName], value)) {
        throw new Error(`${label} changed in another session (${fieldName}). Reload before saving.`);
      }
    }

    const alreadyDesired = fieldNames.every((fieldName) => sameValue(current[fieldName], desired[fieldName]));
    if (alreadyDesired) return current;

    if (expectedVersion && String(current.updated_date || "") !== expectedVersion) {
      throw new Error(`${label} changed in another session. Reload before saving.`);
    }

    for (const fieldName of fieldNames) {
      if (!sameValue(current[fieldName], expected[fieldName]) && !sameValue(current[fieldName], desired[fieldName])) {
        throw new Error(`${label} changed in another session (${fieldName}). Reload before saving.`);
      }
    }

    const currentVersion = String(current.updated_date || "").trim();
    if (!currentVersion) throw new Error(`${label} is missing its current version. Reload before saving.`);

    let result;
    try {
      result = await entity.updateMany(
        { id: recordId, updated_date: currentVersion },
        { $set: desired },
      );
    } catch (error) {
      const afterError = await entity.get(recordId).catch(() => null);
      if (afterError && fieldNames.every((fieldName) => sameValue(afterError[fieldName], desired[fieldName]))) return afterError;
      throw error;
    }

    if (!result || typeof result.updated !== "number") {
      throw new Error(`${label} conditional-update result could not be verified.`);
    }
    if (result.updated === 1) {
      const saved = await entity.get(recordId).catch(() => null);
      if (!saved) throw new Error(`${label} was updated but could not be re-read.`);
      if (!fieldNames.every((fieldName) => sameValue(saved[fieldName], desired[fieldName]))) {
        throw new Error(`${label} was updated but its stored values do not match this save. Reload and review the record before retrying.`);
      }
      return saved;
    }
  }

  throw new Error(`${label} changed repeatedly while saving. Reload and try again.`);
}

export async function deleteBuilderEntityIfUnchanged({
  entity,
  record,
  guardFields = {},
  label = "Builder record",
} = {}) {
  const id = String(record?.id || "").trim();
  const updatedDate = String(record?.updated_date || "").trim();
  if (!id || !updatedDate || typeof entity?.deleteMany !== "function" || typeof entity?.get !== "function") {
    throw new Error(`${label} could not initialize its concurrency-safe delete.`);
  }
  // Caller guards can narrow the match further but must never widen it past
  // the loaded id + updated_date anchor, so they are spread first.
  const query = { ...guardFields, id, updated_date: updatedDate };
  let result;
  try {
    result = await entity.deleteMany(query);
  } catch (error) {
    let current;
    try {
      current = await entity.get(id);
    } catch (verificationError) {
      if (isEntityNotFoundError(verificationError)) {
        return { deleted: true, convergedAfterResponseLoss: true };
      }
      throw new Error(
        `${label} delete returned an error and its outcome could not be verified. ` +
        `Do not retry blindly; reload before continuing. ${verificationError?.message || ""}`.trim()
      );
    }
    if (!current) return { deleted: true, convergedAfterResponseLoss: true };
    throw error;
  }
  if (!result || typeof result.deleted !== "number") {
    throw new Error(`${label} conditional-delete result could not be verified.`);
  }
  if (result.deleted === 1) return { deleted: true };
  if (result.deleted > 1) {
    throw new Error(`${label} returned an impossible multi-record delete count.`);
  }
  let current;
  try {
    current = await entity.get(id);
  } catch (verificationError) {
    if (isEntityNotFoundError(verificationError)) {
      return { deleted: true, alreadyDeleted: true };
    }
    throw new Error(
      `${label} deletion matched no current version and the record could not be re-read. ` +
      `Do not retry blindly; reload before continuing. ${verificationError?.message || ""}`.trim()
    );
  }
  if (!current) return { deleted: true, alreadyDeleted: true };
  throw new Error(`${label} changed in another session. It was not deleted.`);
}

// Generic aliases let other estimator records reuse the same proven conditional
// persistence behavior without introducing a second concurrency implementation.
export const expectedEntityFields = expectedBuilderEntityFields;
export const replaceEntityFieldsIfUnchanged = replaceBuilderEntityFieldsIfUnchanged;
export const deleteEntityIfUnchanged = deleteBuilderEntityIfUnchanged;

import { base44 } from "@/api/base44Client";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { expectedEstimateFields, replaceEstimateFieldsIfUnchanged } from "@/components/estimator/estimatePersistence";
import { deleteBuilderEntityIfUnchanged, expectedBuilderEntityFields, expectedEntityFields, replaceBuilderEntityFieldsIfUnchanged, replaceEntityFieldsIfUnchanged } from "./builderEntityPersistence";
import { createBuilderPartGroupWithRecovery } from "./builderPartGroupPersistence";
import { staffEntities } from "@/components/staff/staffEntities";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .filter((key) => !["created_by", "created_by_id"].includes(key))
      .map((key) => [key, stableValue(value[key])])
  );
}

function sameSubstantiveValue(a, b) {
  const bothPresent = a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "";
  if (bothPresent && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(num(a) - num(b)) <= 0.005;
  }
  return JSON.stringify(stableValue(a ?? null)) === JSON.stringify(stableValue(b ?? null));
}

export function recoveryPatchDiffers(record, patch) {
  return Object.entries(patch || {}).some(([key, value]) => !sameSubstantiveValue(record?.[key], value));
}

export function builderMutationHash(value) {
  const text = JSON.stringify(stableValue(value ?? null));
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a-${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

export function pendingBuilderMutation(line) {
  const pending = line?.price_acceptance_pending;
  return pending && typeof pending === "object" && String(pending.key || "").trim() ? pending : null;
}

// Recovery markers are durable: the only safe way to clear one is to resume it
// and verify its writes completed. Stale markers are therefore surfaced, never
// silently deleted — a >24h marker means a mutation needs explicit resume review.
export const STALE_PENDING_BUILDER_MUTATION_MS = 24 * 60 * 60 * 1000;

export function pendingBuilderMutationAge(line, now = Date.now()) {
  const pending = pendingBuilderMutation(line);
  const started = Date.parse(pending?.started_at || "");
  return Number.isFinite(started) ? Math.max(0, Number(now) - started) : null;
}

export function pendingBuilderMutationIsStale(line, olderThanMs = STALE_PENDING_BUILDER_MUTATION_MS, now = Date.now()) {
  const age = pendingBuilderMutationAge(line, now);
  return age !== null && age >= Math.max(0, Number(olderThanMs) || 0);
}

export async function markBuilderMutationPending({ estimate, builder, pending }) {
  if (!estimate?.id || !builder?.id || !pending?.key) {
    throw new Error("Builder mutation recovery could not be initialized.");
  }
  const latestEstimate = await staffEntities.AllInOneEstimate.get(estimate.id);
  if (!latestEstimate) throw new Error("Estimate could not be verified before starting this Builder mutation.");
  if (
    estimate.updated_date &&
    latestEstimate.updated_date &&
    estimate.updated_date !== latestEstimate.updated_date
  ) {
    throw new Error("This estimate changed in another session before the Builder mutation could start. No Product or Part pricing was changed.");
  }
  const latestLine = (latestEstimate.line_items || []).find((item) => item.builder_product_id === builder.id);
  if (!latestLine) throw new Error("This Product is no longer part of the estimate. No Product or Part pricing was changed.");
  const lineItems = (latestEstimate.line_items || []).map((item) =>
    item.builder_product_id === builder.id
      ? { ...item, price_acceptance_pending: pending }
      : item
  );
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId: estimate.id,
    expectedFields: expectedEstimateFields(latestEstimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Builder mutation recovery marker",
  });

  const [markedEstimate, currentBuilder, currentParts] = await Promise.all([
    staffEntities.AllInOneEstimate.get(estimate.id),
    staffEntities.BuilderProduct.get(builder.id),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder recovery Parts" }),
  ]);
  const markedLine = (markedEstimate?.line_items || []).find((item) => item.builder_product_id === builder.id);
  const canonicalPending = pendingBuilderMutation(markedLine);
  if (!canonicalPending || canonicalPending.key !== pending.key) {
    throw new Error("Another Builder mutation won the recovery marker race. Reload before continuing.");
  }
  return { markedEstimate, currentBuilder, currentParts, markedLine, canonicalPending };
}

function validatePendingBuilderMutation(pending, { estimateId, builder, line }) {
  if (!pending || !String(pending.kind || "").startsWith("builder_")) {
    throw new Error("The pending Builder recovery marker is invalid. No pricing or Part change was continued.");
  }
  if (
    String(pending.estimate_id || "") !== String(estimateId || "") ||
    String(pending.builder_product_id || "") !== String(builder?.id || "") ||
    (pending.estimate_line_id && line?.line_id && pending.estimate_line_id !== line.line_id)
  ) {
    throw new Error("The pending Builder recovery marker no longer matches this Estimate Product.");
  }
}

function currentSignShopSessionToken() {
  try {
    if (typeof window === "undefined") return "";
    return String(window.localStorage?.getItem("sss_session_token") || "").trim();
  } catch {
    return "";
  }
}

export async function ensureBuilderPriceRevision(idempotencyKey, revision) {
  const sessionToken = currentSignShopSessionToken();
  if (!sessionToken) {
    throw new Error("Your signed sign-shop session is no longer available. Sign in again before changing Builder pricing.");
  }
  const response = await base44.functions.invoke("ensureBuilderPriceRevision", {
    idempotency_key: idempotencyKey,
    revision,
    session_token: sessionToken,
  });
  const result = response?.data || response;
  if (result?.error) throw new Error(result.error);
  if (!result?.revision?.id) throw new Error("Builder price revision could not be verified after recording.");
  return result.revision;
}

async function applyPendingSourcePatch(pending) {
  const sourceEntity = String(pending?.source_entity || "").trim();
  const sourceProjectId = String(pending?.source_project_id || "").trim();
  const sourcePatch = pending?.source_patch && typeof pending.source_patch === "object" ? pending.source_patch : null;
  if (!sourceEntity || !sourceProjectId || !sourcePatch || Object.keys(sourcePatch).length === 0) return null;
  const entity = staffEntities[sourceEntity];
  if (!entity?.get || !entity?.updateMany) throw new Error("The Builder source entity needed for recovery is unavailable.");
  const current = await entity.get(sourceProjectId);
  if (!current) throw new Error("The Builder source project could not be verified while recovering the pending mutation.");
  if (!recoveryPatchDiffers(current, sourcePatch)) return current;

  const expected = String(pending?.source_updated_date_before || "").trim();
  const actual = String(current?.updated_date || "").trim();
  if (expected && actual && expected !== actual) {
    throw new Error("The Builder source project changed while reattachment was pending. The recovery marker was retained and no unrelated source edit was overwritten.");
  }
  return replaceEntityFieldsIfUnchanged({
    entity,
    id: sourceProjectId,
    expectedUpdatedAt: current.updated_date || "",
    expectedFields: expectedEntityFields(current, sourcePatch),
    nextFields: sourcePatch,
    label: "Builder source recovery",
  });
}

async function applyPendingGroupCreatePlan(pending, builderProductId) {
  const plan = pending?.group_create_plan;
  const groups = Array.isArray(plan?.groups) ? plan.groups : [];
  if (!groups.length) return new Map();

  const currentGroups = await loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder recovery Part Groups" });
  if (!Array.isArray(currentGroups) || currentGroups.some((group) => String(group?.builder_product_id || "") !== String(builderProductId || ""))) {
    throw new Error("Part Groups could not be verified while recovering the pending Builder mutation.");
  }
  const byKey = new Map(currentGroups.map((group) => [group.group_key, group]));
  const resolvedIds = new Map();

  for (const step of groups) {
    const groupKey = String(step?.group_key || step?.data?.group_key || "").trim();
    const data = step?.data && typeof step.data === "object" ? step.data : null;
    if (!groupKey || !data) throw new Error("A stored Part Group create step is invalid. Recovery was stopped before creating anything else.");
    const { record: resolved } = await createBuilderPartGroupWithRecovery({
      entity: staffEntities.BuilderPartGroup,
      data,
      label: `Builder Part Group “${data.group_name || groupKey}” recovery create`,
    });
    if (!resolved?.id) throw new Error("A Part Group could not be verified after creation while recovering the Builder mutation.");
    byKey.set(groupKey, resolved);
    resolvedIds.set(groupKey, resolved.id);
  }
  return resolvedIds;
}

function resolvePendingPartGroupRefs(plan, groupIds) {
  if (!Array.isArray(plan?.part_updates) || !groupIds?.size) return plan;
  return {
    ...plan,
    part_updates: plan.part_updates.map((step) => {
      const groupKey = String(step?.part_group_key_ref || "").trim();
      if (!groupKey) return step;
      const groupId = groupIds.get(groupKey);
      if (!groupId) throw new Error("A stored Part could not resolve its pending Part Group during recovery.");
      return {
        ...step,
        data: step?.data ? { ...step.data, part_group_id: groupId } : step.data,
        patch: step?.patch ? { ...step.patch, part_group_id: groupId } : step.patch,
      };
    }),
  };
}

async function verifyPendingPreconditions(pending, builderProductId) {
  const plan = pending?.precondition_plan;
  if (!plan || typeof plan !== "object") return;

  const createGroups = Array.isArray(pending?.group_create_plan?.groups) ? pending.group_create_plan.groups : [];
  let createdGroupsByKey = new Map();
  if (createGroups.length) {
    const currentGroups = await loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder recovery Part Groups" });
    if (!Array.isArray(currentGroups)) throw new Error("Part Groups could not be verified while checking Builder mutation preconditions.");
    createdGroupsByKey = new Map(currentGroups.map((group) => [group.group_key, group]));
  }

  for (const step of plan.groups || []) {
    const group = await staffEntities.BuilderPartGroup.get(step.id);
    if (!group) {
      if (step.allow_missing_if_applied) continue;
      throw new Error("A source Part Group disappeared while the Builder mutation was pending.");
    }
    if (String(group.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A source Part Group changed ownership while the Builder mutation was pending.");
    }
    const sourceMatches =
      (!step.expected_patch || !recoveryPatchDiffers(group, step.expected_patch)) &&
      (!step.expected_updated_date || !group.updated_date || String(step.expected_updated_date) === String(group.updated_date));
    if (sourceMatches) continue;
    if (step.target_patch && !recoveryPatchDiffers(group, step.target_patch)) continue;
    throw new Error(`Part Group “${group.group_name || "Part Group"}” changed while the Builder mutation was pending. No unrelated Group edit was overwritten.`);
  }

  for (const step of plan.parts || []) {
    const part = await staffEntities.BuilderPart.get(step.id);
    if (!part || String(part.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A source Part changed ownership or disappeared while the Builder mutation was pending.");
    }
    const sourceMatches =
      (!step.expected_patch || !recoveryPatchDiffers(part, step.expected_patch)) &&
      (!step.expected_updated_date || !part.updated_date || String(step.expected_updated_date) === String(part.updated_date));
    if (sourceMatches) continue;
    if (step.target_patch && !recoveryPatchDiffers(part, step.target_patch)) continue;
    if (step.target_group_key_ref) {
      const targetGroup = createdGroupsByKey.get(step.target_group_key_ref);
      if (targetGroup?.id && String(part.part_group_id || "") === String(targetGroup.id)) continue;
    }
    throw new Error(`Part “${part.part_name || "Part"}” changed while the Builder mutation was pending. No unrelated Part edit was overwritten.`);
  }
}

async function applyPendingDeletePlan(pending, builderProductId) {
  const plan = pending?.delete_plan;
  if (!plan || typeof plan !== "object") return { partDeletes: 0, groupDeletes: 0 };

  // Verify every surviving delete target before deleting any of them. This keeps
  // a concurrent Part Group edit from being discovered only after the Part has
  // already been removed. Missing targets are treated as already-applied steps.
  const verifiedParts = [];
  const verifiedGroups = [];
  for (const step of plan.parts || []) {
    const part = await staffEntities.BuilderPart.get(step.id);
    if (!part) continue;
    if (String(part.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A Part scheduled for deletion changed ownership while the Builder mutation was pending.");
    }
    const expected = String(step.expected_updated_date || "").trim();
    const current = String(part.updated_date || "").trim();
    if (expected && current && expected !== current) {
      throw new Error(`Part “${part.part_name || "Part"}” changed while removal was pending. No unrelated Part edit was deleted.`);
    }
    verifiedParts.push(part);
  }
  for (const step of plan.groups || []) {
    const group = await staffEntities.BuilderPartGroup.get(step.id);
    if (!group) continue;
    if (String(group.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error("A Part Group scheduled for deletion changed ownership while the Builder mutation was pending.");
    }
    const expected = String(step.expected_updated_date || "").trim();
    const current = String(group.updated_date || "").trim();
    if (expected && current && expected !== current) {
      throw new Error(`Part Group “${group.group_name || "Part Group"}” changed while removal was pending. No unrelated group edit was deleted.`);
    }
    verifiedGroups.push(group);
  }

  let partDeletes = 0;
  let groupDeletes = 0;
  for (const part of verifiedParts) {
    await deleteBuilderEntityIfUnchanged({
      entity: staffEntities.BuilderPart,
      record: part,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part “${part.part_name || "Part"}”`,
    });
    partDeletes += 1;
  }
  for (const group of verifiedGroups) {
    await deleteBuilderEntityIfUnchanged({
      entity: staffEntities.BuilderPartGroup,
      record: group,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part Group “${group.group_name || "Part Group"}”`,
    });
    groupDeletes += 1;
  }
  return { partDeletes, groupDeletes };
}

export async function resumeBuilderMutation({
  estimateId,
  estimate,
  builder,
  parts,
  line,
  pending,
  applyPartPlan,
}) {
  validatePendingBuilderMutation(pending, { estimateId, builder, line });
  if (pending.kind === "builder_part_group_move") {
    throw new Error("This pending Part Group move must be resumed with its two-Product recovery action.");
  }
  if (pending.kind === "builder_product_remove") {
    throw new Error("This pending Product removal must be resumed with Resume Product Remove.");
  }
  if (typeof applyPartPlan !== "function") throw new Error("Builder recovery could not apply its stored Part plan.");
  await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });

  if (!Array.isArray(parts) || parts.some((part) => part?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified while recovering the pending Builder mutation.");
  }
  const plan = pending.part_acceptance_plan || {};
  const builderPatch = pending.builder_patch || {};
  const preflightBuilder = await staffEntities.BuilderProduct.get(builder.id);
  if (!preflightBuilder?.id) throw new Error("Builder Product could not be verified before recovering the pending mutation.");
  if (recoveryPatchDiffers(preflightBuilder, builderPatch)) {
    const expectedBuilderUpdatedAt = String(pending.builder_updated_date_before || "").trim();
    const currentBuilderUpdatedAt = String(preflightBuilder.updated_date || "").trim();
    if (expectedBuilderUpdatedAt && currentBuilderUpdatedAt && expectedBuilderUpdatedAt !== currentBuilderUpdatedAt) {
      throw new Error("This Builder Product changed while a Builder mutation was pending. Recovery stopped before applying any stored Part/Group writes.");
    }
  }
  await verifyPendingPreconditions(pending, builder.id);
  await applyPendingSourcePatch(pending);
  await applyPendingDeletePlan(pending, builder.id);
  const groupIds = await applyPendingGroupCreatePlan(pending, builder.id);
  const resolvedPlan = resolvePendingPartGroupRefs(plan, groupIds);
  // Re-read Parts inside the applier instead of trusting the post-marker snapshot.
  // This closes the race where another session edits a Part after marker verification
  // but before the exact stored Part patch is written.
  await applyPartPlan(builder.id, resolvedPlan);
  if (pending.post_part_delete_plan) {
    await applyPendingDeletePlan({ delete_plan: pending.post_part_delete_plan }, builder.id);
  }

  let revision = pending.revision || {};
  const changedParts = Array.isArray(revision.changed_parts) ? revision.changed_parts : [];
  if (changedParts.some((part) => part?.part_key_ref || part?.new_group_key_ref)) {
    const currentParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder recovery Parts" });
    if (!Array.isArray(currentParts)) throw new Error("Created Parts could not be verified before recording the Builder revision.");
    const partsByKey = new Map(currentParts.map((part) => [part.part_key, part]));
    revision = {
      ...revision,
      changed_parts: changedParts.map((part) => {
        const hydrated = { ...part };
        if (hydrated.part_key_ref) {
          const createdPart = partsByKey.get(hydrated.part_key_ref);
          if (!createdPart?.id) throw new Error("A created Part could not be resolved for the Builder revision audit.");
          hydrated.part_id = createdPart.id;
          hydrated.part_key = createdPart.part_key;
          delete hydrated.part_key_ref;
        }
        if (hydrated.new_group_key_ref) {
          const createdGroupId = groupIds.get(hydrated.new_group_key_ref);
          if (!createdGroupId) throw new Error("A created Part Group could not be resolved for the Builder revision audit.");
          hydrated.new_group_id = createdGroupId;
          delete hydrated.new_group_key_ref;
        }
        return hydrated;
      }),
    };
  }
  if (!pending.skip_revision) {
    await ensureBuilderPriceRevision(pending.key, revision);
  }

  const currentBuilder = await staffEntities.BuilderProduct.get(builder.id);
  if (!currentBuilder?.id) throw new Error("Builder Product could not be verified while completing the pending mutation.");
  if (recoveryPatchDiffers(currentBuilder, builderPatch)) {
    const expectedBuilderUpdatedAt = String(pending.builder_updated_date_before || "").trim();
    const currentBuilderUpdatedAt = String(currentBuilder.updated_date || "").trim();
    if (expectedBuilderUpdatedAt && currentBuilderUpdatedAt && expectedBuilderUpdatedAt !== currentBuilderUpdatedAt) {
      throw new Error("This Builder Product changed while a Builder mutation was pending. The recovery marker was retained and no unrelated Builder edit was overwritten.");
    }
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: builder.id,
      expectedUpdatedAt: currentBuilder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(currentBuilder, builderPatch),
      nextFields: builderPatch,
      guardFields: { estimate_id: currentBuilder.estimate_id },
      label: "Builder Product recovery completion",
    });
  }

  const latestEstimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!latestEstimate) throw new Error("Estimate could not be verified while completing the pending Builder mutation.");
  const latestLine = (latestEstimate.line_items || []).find((item) => item.builder_product_id === builder.id);
  if (!latestLine) throw new Error("This Product is no longer part of the estimate. The pending Builder recovery marker could not be completed.");
  const latestPending = pendingBuilderMutation(latestLine);
  const linePatch = pending.line_patch || {};

  if (!latestPending) {
    if (!recoveryPatchDiffers(latestLine, linePatch)) {
      return {
        blocked: false,
        recovered: true,
        alreadyCompleted: true,
        changedParts: resolvedPlan.changed_parts || [],
        line: latestLine,
      };
    }
    throw new Error("The Builder recovery marker disappeared before the accepted Estimate line was verified. Reload before continuing.");
  }
  if (latestPending.key !== pending.key) {
    throw new Error("A different Builder recovery operation is now active for this Product. Reload before continuing.");
  }
  await assertEstimateProductMutationAllowed(latestEstimate, { allowPriceAcceptanceKey: pending.key });

  const lineItems = (latestEstimate.line_items || []).map((item) =>
    item.builder_product_id === builder.id
      ? { ...item, ...linePatch, price_acceptance_pending: {} }
      : item
  );
  const updateResult = await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(latestEstimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Builder mutation recovery completion",
  });
  const completedLine = (updateResult?.line_items || lineItems).find((item) => item.builder_product_id === builder.id) || null;
  return {
    blocked: false,
    recovered: true,
    changedParts: resolvedPlan.changed_parts || [],
    line: completedLine,
  };
}

import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { staffEntities } from "@/components/staff/staffEntities";

// String fields can differ only by stray or repeated whitespace; normalize
// whitespace (but not case) so stored rows match their intended patches.
const cleanString = (value) => String(value ?? "").trim().replace(/\s+/g, " ");

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    // Values compared here are individual patch fields, not whole entity rows.
    // Preserve nested ids and metadata because they can be substantive Builder
    // item identity inside arrays/objects.
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  if (typeof a === "string" && typeof b === "string") {
    return cleanString(a) === cleanString(b);
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

export function sourcePatchMatches(record, patch) {
  if (!record || !patch) return false;
  return Object.entries(patch).every(([key, value]) => sameValue(record?.[key], value));
}

export async function preflightBuilderSourceMutation({ estimateId = "" } = {}) {
  if (!estimateId) return null;
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate?.id) throw new Error("Estimate could not be verified before saving this Builder source.");
  await assertEstimateProductMutationAllowed(estimate);
  return estimate;
}

export async function updateBuilderSourceProject({
  entity,
  sourceId,
  expectedUpdatedAt,
  data,
  estimateId = "",
  label = "Builder source project",
}) {
  if (!entity?.updateMany || !entity?.get || !sourceId) {
    throw new Error(`${label} could not initialize its concurrency-safe update.`);
  }
  const expected = String(expectedUpdatedAt || "").trim();
  if (!expected) {
    throw new Error(`${label} is missing its loaded version. Reload it before saving.`);
  }

  await preflightBuilderSourceMutation({ estimateId });

  const verified = (record) => !!record && record.id === sourceId
    && typeof record.updated_date === "string" && record.updated_date.length > 0
    && sourcePatchMatches(record, data);
  const conflict = () => new Error(`${label} changed in another session. Reload it before saving.`);

  let result;
  try {
    result = await entity.updateMany(
      { id: sourceId, updated_date: expected },
      { $set: data },
    );
  } catch (error) {
    const current = await entity.get(sourceId).catch(() => null);
    if (verified(current)) return current;
    throw error;
  }

  if (!result || !Number.isInteger(result.updated) || (result.updated !== 0 && result.updated !== 1)) {
    throw new Error(`${label} conditional-update result could not be verified.`);
  }

  if (result.updated === 1) {
    const saved = await entity.get(sourceId).catch(() => null);
    if (!saved) throw new Error(`${label} was updated but could not be re-read.`);
    if (!verified(saved)) throw conflict();
    return saved;
  }

  const current = await entity.get(sourceId).catch(() => null);
  if (verified(current)) {
    // Exact retry after a lost successful response. Do not rewrite the row merely
    // to refresh its timestamp; reuse the already-persisted intended state.
    return current;
  }

  throw conflict();
}
